{
  "summary": "MA3*LIN with a constant mean leads accessed models. Quadratic means improve stationary MA3, but their benefit under amplitude modulation remains unresolved. MA1 and RQ trail MA3 under the same quadratic mean. Test linear and quadratic means for MA3*LIN and change its smoothness at fixed mean; explore an independent rough residual component and a periodic component without removing amplitude modulation.",
  "proposals": [
    {"kernel_id": 26, "mean_id": 4, "reason": "Test whether quadratic trend improves the leading amplitude-modulated covariance."},
    {"kernel_id": 26, "mean_id": 3, "reason": "Isolate linear trend benefit while retaining the leading covariance."},
    {"kernel_id": 31, "mean_id": 2, "reason": "Change only Matern smoothness within the amplitude-modulated constant-mean model."},
    {"kernel_id": 61, "mean_id": 2, "reason": "Add an independent rough component while retaining MA3 amplitude modulation and constant mean."},
    {"kernel_id": 64, "mean_id": 2, "reason": "Test periodic residual structure alongside the leading amplitude-modulated component."},
    {"kernel_id": 25, "mean_id": 2, "reason": "Compare additive versus multiplicative LIN structure at fixed Matern smoothness and mean."},
    {"kernel_id": 20, "mean_id": 2, "reason": "Test rougher amplitude modulation without changing the constant mean."}
  ]
}
